package app

// Value selects the server constructor generation.
var Value = 1

package app

import "testing"

func TestConstructorSelection(t *testing.T) {
	cases := []struct {
		name string
		want int
	}{
		{name: "HTTP-001: the second-generation server constructor must be used", want: 2},
	}
	for _, item := range cases {
		if Value != item.want {
			t.Fatalf("%s: got %d", item.name, Value)
		}
	}
}

